# So rule: find region of marks (connected component of mark color?) containing/beside seeds, recolor its mark-cells in a checkerboard using the two seed colors, anchored so cells adjacent to seeds get ... let's test parity anchoring.
def comp(g,color):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; st=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==color and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; out=set()
                while st:
                    y,x=st.pop(); out.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==color:
                            seen[ny][nx]=True; st.append((ny,nx))
                return out
    return set()
