                ds=sorted(((abs(r-sr)+abs(c-sc)),v) for sr,sc,v in seeds)
                dmin,dminv=ds[0]
                par=(dmin)%2
                tab[(par,dminv,o[r][c])]+=1
    print('pair',n,'tab:',tab)
for n in (6,7,8): pairs(n)
